// src/services/api.js  ← COPIA Y PEGA TODO ESTO (versión infalible)
const API_URL = "http://127.0.0.1:8000";

// Función súper simple que nunca falla
async function request(method, endpoint, body = null) {
  const token = localStorage.getItem("access_token");
  const headers = {
    "Content-Type": "application/json",
  };
  if (token) headers["Authorization"] = `Bearer ${token}`;

  const config = { method, headers };
  if (body) config.body = JSON.stringify(body);

  const res = await fetch(API_URL + endpoint, config);
  const data = await res.json();

  if (!res.ok) {
    console.error("Error API:", data);
    throw new Error(data.detail || "Error del servidor");
  }
  return data;
}

export const api = {
  get: (url) => request("GET", url),
  post: (url, body) => request("POST", url, body),
  patch: (url, body) => request("PATCH", url, body),
  put: (url, body) => request("PUT", url, body),
  delete: (url) => request("DELETE", url),
};

// GET MESAS → ESTA ES LA QUE IMPORTA AHORA
export const getMesas = async () => {
  const data = await api.get("/api/mesas/");
  return data;        // ← el router devuelve la lista directamente
};

export const getProductos = async () => await api.get("/api/productos/");
export const getCategorias = async () => await api.get("/api/categorias/");
export const getPedidos = async () => await api.get("/api/pedidos/");

export default api;
